-- mod-temucraft-classes: requirements the client's Spell.dbc lost (forges, anvils, cooking fires, tools, soul shards).
-- The server puts them back on the spells per kind, as Temucraft.Requirements.* says. Values are the stock 3.3.5 ones.
-- Kind: 1 anvil, 2 forge, 3 cooking fire, 4 other focus (alchemy lab, moonwell, altar), 5 tool, 6 soul shard (reagent).
-- Value: the spell focus object, the tool item or the reagent item; Count: the reagent count. Re-runnable.
DROP TABLE IF EXISTS `mod_temucraft_requirement`;
CREATE TABLE `mod_temucraft_requirement` (`SpellID` int unsigned NOT NULL, `Kind` tinyint unsigned NOT NULL, `Value` int unsigned NOT NULL, `Count` int unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`SpellID`, `Kind`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
